fn nisa_ordinary_publication(parser: Parser, bound: bool) -> string {
    let count: int = (parser_get_struct_def_count parser)
    if (or (<= parser.token_count 0) (> (array_length nisa_import_names) 0)) { return "" }
    let mut token_index: int = 0
    while (< token_index parser.token_count) {
        if (== (list_LexerToken_get parser.tokens token_index).token_type LexerTokenType.TOKEN_EXTERN) { return "" }
        set token_index (+ token_index 1)
    }
    if (> parser.imports_count 0) { if (or (not bound) (not (nisa_bound_ordinary_declarations parser))) { return "" } }
    if (or (not nisa_ordinary_ok) (or (<= count 0) (or (> count 128) (or (> (parser_get_enum_count parser) 0) (> (parser_get_union_count parser) 0))))) { return "" }
    if (not (nisa_ordinary_graph parser)) { return "" }
    # I bound new map staging before hex construction; raw local declarations
    # are parsed representations, not a semantic-checker receipt.

